end
function AICProfile.GetProfileNames()
local Names = {}
for Name in pairs(AICProfile.S.ProfileStore.Profiles) do
table.insert(Names, Name)
end
table.sort(Names, function(A, B)
return string.lower(A) < string.lower(B)
end)
